  15 interface AgentState {
  16   selectedAgentId: string | null;
  17   responses: Record<string, Record<string, { prompt: string; response: string }[]>>;
  18   selectedCommandId: string | null;
  19   selectAgent: (agentId: string | null) => void;
  20   setSelectedCommandId: (commandId: string | null) => void;
