  25 const useAgentUIState = create<AgentState>((set) => ({
  26   selectedAgentId: null,
  27   responses: {},
  28   selectedCommandId: null,
  29   selectAgent: (agentId) => set({ selectedAgentId: agentId, selectedCommandId: null, responses: {} }),
  30   setSelectedCommandId: (commandId) => set({ selectedCommandId: commandId }),
  31   setResponse: (agentId, commandId, response) =>
  32     set((state) => {
  33       const newResponses = { ...state.responses };
  34       if (!newResponses[agentId]) newResponses[agentId] = {};
  35       if (!newResponses[agentId][commandId]) newResponses[agentId][commandId] = [];
  36       newResponses[agentId][commandId].push(response);
  37       return { responses: newResponses };
  38     }),
  39   clearResponses: (agentId, commandId) =>
  40     set((state) => {
  41       const newResponses = { ...state.responses };
  42       if (newResponses[agentId]) {
  43         if (commandId) delete newResponses[agentId][commandId];
  44         else delete newResponses[agentId];
  45       }
  46       return { responses: newResponses };
  47     }),
  48 }));
