 132       toast({ title: 'Creation Failed', description: error.message, variant: 'destructive' });
 133       throw error;
 134     }
 135   };
 136 
 137   const updateAgent = async (id: string, data: Partial<AgentProperties>) => {
 138     try {
 139       const updatedAgent = await updateMutation.mutateAsync({ id, data });
 140       toast({ title: 'Agent Updated', description: `"${updatedAgent.name}" has been updated.` });
 141       return updatedAgent;
 142     } catch (error: any) {
 143       toast({ title: 'Update Failed', description: error.message, variant: 'destructive' });
 144       throw error;
